<?php require_once __DIR__.'/config.php'; require_login(); if($_SERVER['REQUEST_METHOD']!=='POST') redirect('index.php'); verify_csrf(); $id=(int)($_POST['id']??0); $data=[trim($_POST['codigo']??''),trim($_POST['nombre']??''),trim($_POST['descripcion']??''),(float)($_POST['precio']??-1),(int)($_POST['stock_actual']??-1),(int)($_POST['stock_minimo']??-1),(int)($_POST['id_categoria']??0)]; if(!$data[0]||!$data[1]||$data[3]<0||$data[4]<0||$data[5]<0||$data[6]<1){flash('danger','Revisa los datos: no pueden faltar campos ni existir valores negativos.');redirect($id?'product_form.php?id='.$id:'product_form.php');} try{$pdo=db(); if($id){$s=$pdo->prepare('UPDATE productos SET codigo=?,nombre=?,descripcion=?,precio=?,stock_actual=?,stock_minimo=?,id_categoria=? WHERE id_producto=?');$s->execute([...$data,$id]);flash('success','Producto actualizado correctamente.');}else{$s=$pdo->prepare('INSERT INTO productos(codigo,nombre,descripcion,precio,stock_actual,stock_minimo,id_categoria) VALUES(?,?,?,?,?,?,?)');$s->execute($data);flash('success','Producto registrado correctamente.');} }catch(PDOException $e){flash('danger',str_contains($e->getMessage(),'Duplicate')?'El código ya existe.':'No fue posible guardar el producto.');redirect($id?'product_form.php?id='.$id:'product_form.php');} redirect('index.php');
